from(bucket: "${bucket}")
    |> range(
        start: v.timeRangeStart,
        stop: v.timeRangeStop
    )

    |> filter(fn: (r) =>
        r["_measurement"] == "${meas}" and
        (
            r["_field"] == "serialboard_id" or
            r["_field"] == "wire_voltage_status"
        )
    )

    |> filter(fn: (r) =>
        r["return_code"] =~ /^${return_code:regex}$/
    )

    // Build slot key
    |> map(fn: (r) => ({
        r with
        slot_key:
            string(v: r.storehouse_id) + "|" +
            string(v: r.pallet_position) + "|" +
            string(v: r.position_id)
    }))

    // Filter selected physical slots
    |> filter(fn: (r) =>
        r.slot_key =~ /^${slot_filter:regex}$/
    )

    // Convert SerialBoard ID and wire voltage status into columns
    |> pivot(
        rowKey: [
            "_time",
            "storehouse_id",
            "pallet_position",
            "position_id",
            "return_code"
        ],
        columnKey: ["_field"],
        valueColumn: "_value"
    )

    // Keep only complete records
    |> filter(fn: (r) =>
        exists r.serialboard_id and
        exists r.wire_voltage_status
    )

    // Keep timestamp temporarily
    |> map(fn: (r) => ({
        _time: r._time,
        serialboard_id: string(v: r.serialboard_id),
        wire_voltage_status: r.wire_voltage_status
    }))

    // One group per SerialBoard ID
    |> group(columns: ["serialboard_id"])

    // Latest record first
    |> sort(
        columns: ["_time"],
        desc: true
    )

    // Keep only latest record for each SerialBoard ID
    |> limit(n: 1)

    // Final Grafana output
    |> map(fn: (r) => ({
        serialboard_id: r.serialboard_id,
        _value: string(v: r.wire_voltage_status)
    }))

