from(bucket: "${bucket}")
    |> range(
        start: v.timeRangeStart,
        stop: v.timeRangeStop
    )

    |> filter(fn: (r) =>
        r["_measurement"] == "${meas}" and
        r["_field"] == "serialboard_id"
    )

    |> filter(fn: (r) =>
        r["return_code"] =~ /^${return_code:regex}$/
    )

    // Build slot key
    |> map(fn: (r) => ({
        r with
        slot_key:
            string(v: r.storehouse_id) + "|" +
            string(v: r.pallet_position) + "|" +
            string(v: r.position_id)
    }))

    // Filter selected physical slots
    |> filter(fn: (r) =>
        r.slot_key =~ /^${slot_filter:regex}$/
    )

    // Keep only L / R
    |> filter(fn: (r) =>
        r["pallet_position"] == "L" or
        r["pallet_position"] == "R"
    )

    // Keep required fields and timestamp
    |> map(fn: (r) => ({
        _time: r._time,
        serialboard_id: string(v: r._value),
        storehouse_id: r.storehouse_id,
        pallet_position: r.pallet_position,
        position_id: r.position_id
    }))

    // One group per SerialBoard ID
    |> group(columns: ["serialboard_id"])

    // Latest location first
    |> sort(
        columns: ["_time"],
        desc: true
    )

    // Keep only latest location
    |> limit(n: 1)

    // Build location
    |> map(fn: (r) => ({
        serialboard_id: r.serialboard_id,
        location:
            "R" +
            string(v: r.storehouse_id) +
            "_" +
            string(v: r.pallet_position)
    }))

    // Merge results for sorting
    |> group()

    // SerialBoard ID ascending
    |> sort(
        columns: ["serialboard_id"],
        desc: false
    )

    // Grafana Stat output
    |> map(fn: (r) => ({
        _field: r.serialboard_id,
        _value: r.location
    }))

from(bucket: "${bucket}")
    |> range(
        start: v.timeRangeStart,
        stop: v.timeRangeStop
    )

    |> filter(fn: (r) =>
        r["_measurement"] == "${meas}" and
        (
            r["_field"] == "serialboard_id" or
            r["_field"] =~ /^wire_voltage_[1-5]$/
        )
    )

    |> filter(fn: (r) =>
        r["return_code"] =~ /^${return_code:regex}$/
    )

    // Build slot key
    |> map(fn: (r) => ({
        r with
        slot_key:
            string(v: r.storehouse_id) + "|" +
            string(v: r.pallet_position) + "|" +
            string(v: r.position_id)
    }))

    // Filter selected physical slots
    |> filter(fn: (r) =>
        r.slot_key =~ /^${slot_filter:regex}$/
    )

    // Convert SerialBoard ID and wire voltages into columns
    |> pivot(
        rowKey: [
            "_time",
            "storehouse_id",
            "pallet_position",
            "position_id",
            "return_code"
        ],
        columnKey: ["_field"],
        valueColumn: "_value"
    )

    // Keep only complete records
    |> filter(fn: (r) =>
        exists r.serialboard_id and
        exists r.wire_voltage_1 and
        exists r.wire_voltage_2 and
        exists r.wire_voltage_3 and
        exists r.wire_voltage_4 and
        exists r.wire_voltage_5
    )

    // Keep timestamp and required fields
    |> map(fn: (r) => ({
        _time: r._time,
        serialboard_id: string(v: r.serialboard_id),
        wire_voltage_1: r.wire_voltage_1,
        wire_voltage_2: r.wire_voltage_2,
        wire_voltage_3: r.wire_voltage_3,
        wire_voltage_4: r.wire_voltage_4,
        wire_voltage_5: r.wire_voltage_5
    }))

    // One group per SerialBoard ID
    |> group(columns: ["serialboard_id"])

    // Latest record first
    |> sort(
        columns: ["_time"],
        desc: true
    )

    // Keep only latest record for each SerialBoard ID
    |> limit(n: 1)

    // Merge all SerialBoard IDs for sorting
    |> group()

    // SerialBoard ID ascending
    |> sort(
        columns: ["serialboard_id"],
        desc: false
    )

    // Final Grafana output
    |> map(fn: (r) => ({
        _field: r.serialboard_id,

        _value:
            string(v: r.wire_voltage_1) + " | " +
            string(v: r.wire_voltage_2) + " | " +
            string(v: r.wire_voltage_3) + " | " +
            string(v: r.wire_voltage_4) + " | " +
            string(v: r.wire_voltage_5) +
            (
                if r.wire_voltage_1 >= 1500 or
                   r.wire_voltage_2 >= 1500 or
                   r.wire_voltage_3 >= 1500 or
                   r.wire_voltage_4 >= 1500 or
                   r.wire_voltage_5 >= 1500
                then "."
                else ""
            )
    }))
